import struct,zlib,zipfile
from pathlib import Path
TABLE=[]
for i in range(256):
 c=i
 for j in range(8): c=(c>>1)^ (0xedb88320 if c&1 else 0)
 TABLE.append(c)
class Crypto:
 def __init__(self,pwd):
  self.a=0x12345678;self.b=0x23456789;self.c=0x34567890
  for x in pwd:self.update(x)
 def update(self,x):
  self.a=(self.a>>8)^TABLE[(self.a^x)&255]
  self.b=((self.b+(self.a&255))*134775813+1)&0xffffffff
  self.c=(self.c>>8)^TABLE[(self.c^(self.b>>24))&255]
 def mask(self):
  v=(self.c|2)&65535
  return ((v*(v^1))>>8)&255
 def enc(self,data):
  out=bytearray()
  for x in data:
   out.append(x^self.mask());self.update(x)
  return bytes(out)
 def dec(self,data):
  out=bytearray()
  for x in data:
   y=x^self.mask();out.append(y);self.update(y)
  return bytes(out)
def makezip(path,pwd,content=b'content for testing',name=b'file.txt',method=0,flags=1,crc_override=None):
 if isinstance(pwd,str):pwd=pwd.encode()
 crc=zlib.crc32(content) if crc_override is None else crc_override
 data=content if method==0 else zlib.compress(content)[2:-4]
 tm=0x2345; dt=0x5678
 hdr=bytes(range(10))+bytes([((crc>>16)&255), (tm>>8) if flags&8 else (crc>>24)])
 encrypted=Crypto(pwd).enc(hdr+data)
 local=struct.pack('<IHHHHHIIIHH',0x04034b50,20,flags,method,tm,dt,crc,len(encrypted),len(content),len(name),0)+name+encrypted
 cen=struct.pack('<IHHHHHHIIIHHHHHII',0x02014b50,20,20,flags,method,tm,dt,crc,len(encrypted),len(content),len(name),0,0,0,0,0,0)+name
 end=struct.pack('<IHHHHIIH',0x06054b50,0,0,1,1,len(cen),len(local),0)
 Path(path).write_bytes(local+cen+end)
if __name__=='__main__':
 d=Path('/tmp/zpf-probes')
 vals=['','a','b','z','A','0','1','9','00','01','10','11','aa','ab','ba','zz','a1','1a','!',' ','\n','\r','é','🔥',' test ','123','test']
