namespace replica {
std::u32string decode_utf8(const std::string &s, bool *valid) {
    bool good = true;
    std::u32string out;
    for (size_t i = 0; i < s.size();) {
        auto a = static_cast<unsigned char>(s[i]);
        uint32_t cp = a;
        size_t n = 1;
        if (a < 0x80) {}
        else if (a >= 0xc2 && a <= 0xdf) { n = 2; cp = a & 31; }
        else if (a >= 0xe0 && a <= 0xef) { n = 3; cp = a & 15; }
        else if (a >= 0xf0 && a <= 0xf4) { n = 4; cp = a & 7; }
        else { good = false; out.push_back(0xfffd); ++i; continue; }
        bool ok = i + n <= s.size();
        if (ok) {
            for (size_t j = 1; j < n; ++j) {
                unsigned char c = s[i+j];
                if ((c & 0xc0) != 0x80) { ok = false; break; }
                cp = (cp << 6) | (c & 63);
            }
            if ((n == 2 && cp < 0x80) || (n == 3 && cp < 0x800) ||
                (n == 4 && cp < 0x10000) || cp > 0x10ffff ||
                (cp >= 0xd800 && cp <= 0xdfff)) ok = false;
        }
        if (!ok) { good = false; out.push_back(0xfffd); ++i; }
        else { out.push_back(static_cast<char32_t>(cp)); i += n; }
    }
    if (valid) *valid = good;
    return out;
}
std::string encode_utf8(const std::u32string &s) {
    std::string r;
    for (uint32_t cp : s) {
        if (cp < 0x80) r += static_cast<char>(cp);
        else if (cp < 0x800) {
            r += static_cast<char>(0xc0 | (cp >> 6));
            r += static_cast<char>(0x80 | (cp & 63));
        } else if (cp < 0x10000) {
            r += static_cast<char>(0xe0 | (cp >> 12));
            r += static_cast<char>(0x80 | ((cp >> 6) & 63));
            r += static_cast<char>(0x80 | (cp & 63));
        } else {
            r += static_cast<char>(0xf0 | (cp >> 18));
            r += static_cast<char>(0x80 | ((cp >> 12) & 63));
            r += static_cast<char>(0x80 | ((cp >> 6) & 63));
            r += static_cast<char>(0x80 | (cp & 63));
        }
    }
    return r;
}
std::string rust_debug(const std::string &s) {
    std::string out = "\"";
    for (char32_t cp : decode_utf8(s)) {
        if (cp == '\n') out += "\\n";
        else if (cp == '\r') out += "\\r";
        else if (cp == '\t') out += "\\t";
        else if (cp == 0) out += "\\0";
        else if (cp == '\\') out += "\\\\";
        else if (cp == '"') out += "\\\"";
        else if (cp < 32 || (cp >= 0x7f && cp < 0xa0) || cp == 0x2028 || cp == 0x2029) {
            std::ostringstream o; o << "\\u{" << std::hex << uint32_t(cp) << '}'; out += o.str();
        } else out += encode_utf8(std::u32string(1,cp));
    }
    return out + '"';
}
std::string system_error(int number) {
    return std::string(std::strerror(number)) + " (os error " + std::to_string(number) + ")";
}
Bytes read_file(const std::string &path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) io_failure(system_error(errno));
    Bytes result;
    char buf[65536];
    while (in) {
        in.read(buf, sizeof(buf));
        result.insert(result.end(), buf, buf + in.gcount());
    }
    if (in.bad()) io_failure(system_error(errno));
    return result;
}
[[noreturn]] void cli_failure(const std::string &s) {
    throw Failure(1, "CLI argument error - " + rust_debug(s) + "\n");
}
[[noreturn]] void io_failure(const std::string &s) {
    throw Failure(1, "standard I/O error - " + s + "\n");
}
[[noreturn]] void zip_failure(const std::string &s, bool unsupported) {
    throw Failure(1, "Invalid zip file error - " + std::string(unsupported ? "unsupported" : "invalid") + " Zip archive: " + s + "\n");
}
std::string panic_message(const std::string &thread, const std::string &location,
                          const std::string &reason, bool note) {
    std::string s = "\nthread '" + thread + "' (" + std::to_string(syscall(SYS_gettid)) + ") panicked at " + location + ":\n" + reason + "\n";
    if (note) s += "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n";
    return s;
}
}
