#include "cli.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdlib>
#include <map>
#include <set>
#include <sys/stat.h>
#include <thread>
#include <unistd.h>
#include <sched.h>

namespace replica {
namespace {
const std::vector<std::string> names = {"inputFile", "workers", "passwordDictionary", "charset", "charsetFile", "minPasswordLen", "maxPasswordLen", "fileNumber", "startingPassword", "help", "version"};
const std::string footer = "\nFor more information, try '--help'.\n";
std::string label(const std::string &name) {
    if (name == "help" || name == "version") return "--" + name;
    return "--" + name + " <" + name + ">";
}
std::string full_usage(const std::string &bin) {
    return "Usage: " + bin + " [OPTIONS] --inputFile <inputFile>\n";
}
std::string usage(const std::string &bin, const std::vector<std::string> &seen) {
    std::string out = "Usage: " + bin + " --inputFile <inputFile>";
    std::set<std::string> used = {"inputFile"};
    for (auto &v : seen) if (used.insert(v).second) out += ' ' + label(v);
    return out + '\n';
}
std::string help(const std::string &bin) {
    return "Find the password of protected ZIP files\n\n" + full_usage(bin) +
        "\nOptions:\n"
        "  -i, --inputFile <inputFile>                    path to zip input file\n"
        "  -w, --workers <workers>                        number of workers\n"
        "  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file\n"
        "  -c, --charset <charset>                        charset to use to generate password [default: lud]\n"
        "      --charsetFile <charsetFile>                path to a charset file\n"
        "      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]\n"
        "      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]\n"
        "      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]\n"
        "  -s, --startingPassword <startingPassword>      password to start from\n"
        "  -h, --help                                     Print help\n"
        "  -V, --version                                  Print version\n";
}
std::string short_name(char c) {
    switch (c) {
    case 'i': return "inputFile";
    case 'w': return "workers";
    case 'p': return "passwordDictionary";
    case 'c': return "charset";
    case 's': return "startingPassword";
    case 'h': return "help";
    case 'V': return "version";
    default: return "";
    }
}
bool long_exists(const std::string &s) {
    return std::find(names.begin(), names.end(), s) != names.end();
}
// Compare misspelled long options with their documented spellings.
double similarity(const std::string &a, const std::string &b) {
    if (a == b) return 1;
    if (a.empty() || b.empty()) return 0;
    int range = std::max(a.size(), b.size()) / 2 - 1;
    range = std::max(range, 0);
    std::vector<bool> am(a.size()), bm(b.size());
    int count = 0;
    for (int i = 0; i < int(a.size()); ++i) {
        for (int j = std::max(0, i-range); j < std::min(int(b.size()), i+range+1); ++j) {
            if (!bm[j] && a[i] == b[j]) { am[i] = bm[j] = true; ++count; break; }
        }
    }
    if (!count) return 0;
    int diff = 0, j = 0;
    for (int i = 0; i < int(a.size()); ++i) if (am[i]) {
        while (!bm[j]) ++j;
        if (a[i] != b[j]) ++diff;
        ++j;
    }
    double c = count;
    double score = (c/a.size() + c/b.size() + (c - diff/2.0)/c) / 3;
    int prefix = 0;
    while (prefix < 4 && prefix < int(std::min(a.size(),b.size())) && a[prefix] == b[prefix]) ++prefix;
    if (score > .7) score += prefix*.1*(1-score);
    return score;
}
std::string suggestion(const std::string &token) {
    std::string best; double score = .8;
    for (auto &s : names) {
        double v = similarity(token, s);
        if (v > score) { score = v; best = s; }
    }
    return best;
}
[[noreturn]] void unexpected(const std::string &token, const std::string &bin,
                           const std::vector<std::string> &seen, bool positional = false) {
    std::string err = "error: unexpected argument '" + token + "' found\n\n";
    std::string tip;
    if (!positional && token.rfind("--",0) == 0) tip = suggestion(token.substr(2));
    if (!tip.empty()) {
        err += "  tip: a similar argument exists: '--" + tip + "'\n\n";
        auto used = seen; used.push_back(tip);
        err += usage(bin,used);
    } else if (!positional && token.rfind("--",0) == 0 && !seen.empty()) err += usage(bin,seen);
    else err += full_usage(bin);
    throw Failure(2, err + footer);
}
[[noreturn]] void missing_value(const std::string &name) {
    throw Failure(2, "error: a value is required for '" + label(name) + "' but none was supplied\n" + footer);
}
uint64_t parse_number(const std::string &value, const std::string &name) {
    std::string reason;
    uint64_t n = 0;
    size_t i = 0;
    if (value.empty()) reason = "cannot parse integer from empty string";
    else {
        if (value[0] == '+') ++i;
        if (i == value.size()) reason = "invalid digit found in string";
        for (; i < value.size() && reason.empty(); ++i) {
            unsigned c = static_cast<unsigned char>(value[i]);
            if (c < '0' || c > '9') reason = "invalid digit found in string";
            else if (n > (UINT64_MAX - (c-'0')) / 10) reason = "number too large to fit in target type";
            else n = n*10 + c-'0';
        }
    }
    if (!reason.empty()) throw Failure(2, "error: invalid value '" + value + "' for '" + label(name) + "': " + reason + "\n" + footer);
    return n;
}
bool is_file(const std::string &path) {
    struct stat s;
    return stat(path.c_str(), &s) == 0 && S_ISREG(s.st_mode);
}
}
Options parse_options(int argc, char **argv) {
    std::string bin = argc > 0 ? argv[0] : "executable";
    auto slash = bin.find_last_of('/');
    if (slash != std::string::npos) bin.erase(0,slash+1);
    if (bin.empty()) bin = "executable";
    Options o;
    cpu_set_t cpus;
    if (sched_getaffinity(0,sizeof(cpus),&cpus) == 0) o.workers = std::max(1,CPU_COUNT(&cpus));
    else o.workers = std::max(1u,std::thread::hardware_concurrency());
    std::map<std::string,std::string> vals;
    std::vector<std::string> seen;
    bool end_flags = false;
    for (int i = 1; i < argc; ++i) {
        std::string token = argv[i];
        if (end_flags) unexpected(token,bin,seen,true);
        if (token == "--") { end_flags = true; continue; }
        std::string name, value;
        bool has_value = false;
        if (token.rfind("--",0) == 0) {
            size_t eq = token.find('=');
            name = token.substr(2,eq == std::string::npos ? eq : eq-2);
            if (!long_exists(name)) unexpected("--"+name,bin,seen);
            if (eq != std::string::npos) { has_value = true; value = token.substr(eq+1); }
        } else if (token.size() > 1 && token[0] == '-') {
            name = short_name(token[1]);
            if (name.empty()) unexpected(token.substr(0,2),bin,seen);
            if (token.size() > 2 && name != "help" && name != "version") {
                has_value = true; value = token.substr(token[2] == '=' ? 3 : 2);
            }
        } else unexpected(token,bin,seen,true);
        if (name == "help" || name == "version") {
            if (has_value) throw Failure(2,"error: unexpected value '"+value+"' for '--"+name+"' found; no more were expected\n\n"+usage(bin,{name})+footer);
            if (name == "help") throw Failure(0,help(bin),true);
            throw Failure(0,"zip-password-finder 0.10.3\n",true);
        }
        if (!has_value) {
            if (i+1 == argc) missing_value(name);
            std::string next = argv[i+1];
            if (next.size() > 1 && next[0] == '-') {
                if (next == "--") missing_value(name);
                if (next.rfind("--",0) == 0) {
                    auto raw = next.substr(2,next.find('=') == std::string::npos ? std::string::npos : next.find('=')-2);
                    if (long_exists(raw)) missing_value(name);
                    unexpected("--"+raw,bin,seen);
                } else {
                    if (!short_name(next[1]).empty()) missing_value(name);
                    unexpected(next.substr(0,2),bin,seen);
                }
            }
            value = next; ++i;
        }
        if (vals.count(name)) throw Failure(2,"error: the argument '"+label(name)+"' cannot be used multiple times\n\n"+full_usage(bin)+footer);
        if (name == "workers") o.workers = parse_number(value,name);
        else if (name == "minPasswordLen") o.min_length = parse_number(value,name);
        else if (name == "maxPasswordLen") o.max_length = parse_number(value,name);
        else if (name == "fileNumber") o.file_number = parse_number(value,name);
        else if (name == "inputFile") o.input = value;
        else if (name == "charset") o.charset_codes = value;
        else if (name == "passwordDictionary") o.dictionary = value;
        else if (name == "charsetFile") o.charset_file = value;
        else if (name == "startingPassword") o.starting = value;
        vals[name] = value;
        seen.push_back(name);
    }
    if (!vals.count("inputFile")) throw Failure(2,"error: the following required arguments were not provided:\n  --inputFile <inputFile>\n\n"+usage(bin,seen)+footer);
    return o;
}
void validate_options(Options &o) {
    if (!is_file(o.input)) cli_failure("'inputFile' does not exist");
    if (o.dictionary && !is_file(*o.dictionary)) cli_failure("'passwordDictionary' does not exist");
    if (o.charset_file && !is_file(*o.charset_file)) cli_failure("'charsetFile' does not exist");
    if (!o.workers) cli_failure("'workers' must be positive");
    if (!o.min_length) cli_failure("'minPasswordLen' must be positive");
    if (!o.max_length) cli_failure("'maxPasswordLen' must be positive");
    if (o.max_length < o.min_length) cli_failure("'maxPasswordLen' must be equal or greater than 'minPasswordLen'");
    if (o.dictionary) {
        if (o.starting) cli_failure("'startingPassword' cannot be used with a dictionary file");
        return;
    }
    if (o.charset_file) {
        auto bytes = read_file(*o.charset_file);
        bool valid;
        o.charset = decode_utf8(std::string(bytes.begin(),bytes.end()),&valid);
        if (!valid) io_failure("stream did not contain valid UTF-8");
    } else {
        for (auto c : decode_utf8(o.charset_codes)) {
            switch (c) {
            case U'l': o.charset += U"abcdefghijklmnopqrstuvwxyz"; break;
            case U'u': o.charset += U"ABCDEFGHIJKLMNOPQRSTUVWXYZ"; break;
            case U'd': o.charset += U"0123456789"; break;
            case U'h': o.charset += U"0123456789abcdef"; break;
            case U'H': o.charset += U"0123456789ABCDEF"; break;
            case U's': o.charset += U" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"; break;
            default: cli_failure("Unknown charset option '" + encode_utf8(std::u32string(1,c)) + "'");
            }
        }
    }
    std::sort(o.charset.begin(),o.charset.end());
    o.charset.erase(std::unique(o.charset.begin(),o.charset.end()),o.charset.end());
    if (o.starting) {
        auto s = decode_utf8(*o.starting);
        if (s.size() < o.min_length || s.size() > o.max_length) cli_failure("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration");
        for (auto c : s) if (!std::binary_search(o.charset.begin(),o.charset.end(),c)) cli_failure("'startingPassword' uses characters out of the generation charset");
    }
}
}
