// Compare misspelled long options with their documented spellings.
double similarity(const std::string &a, const std::string &b) {
    if (a == b) return 1;
    if (a.empty() || b.empty()) return 0;
    int range = std::max(a.size(), b.size()) / 2 - 1;
    range = std::max(range, 0);
    std::vector<bool> am(a.size()), bm(b.size());
    int count = 0;
    for (int i = 0; i < int(a.size()); ++i) {
        for (int j = std::max(0, i-range); j < std::min(int(b.size()), i+range+1); ++j) {
            if (!bm[j] && a[i] == b[j]) { am[i] = bm[j] = true; ++count; break; }
        }
    }
    if (!count) return 0;
    int diff = 0, j = 0;
    for (int i = 0; i < int(a.size()); ++i) if (am[i]) {
        while (!bm[j]) ++j;
        if (a[i] != b[j]) ++diff;
        ++j;
    }
    double c = count;
    double score = (c/a.size() + c/b.size() + (c - diff/2.0)/c) / 3;
    int prefix = 0;
    while (prefix < 4 && prefix < int(std::min(a.size(),b.size())) && a[prefix] == b[prefix]) ++prefix;
    if (score > .7) score += prefix*.1*(1-score);
    return score;
}
std::string suggestion(const std::string &token) {
    std::string best; double score = .8;
    for (auto &s : names) {
        double v = similarity(token, s);
