    if (!tip.empty()) {
        err += "  tip: a similar argument exists: '--" + tip + "'\n\n";
        auto used = seen; used.push_back(tip);
        err += usage(bin,used);
    } else if (!positional && token.rfind("--",0) == 0 && !seen.empty()) err += usage(bin,seen);
