    size_t i = 0;
    if (value.empty()) reason = "cannot parse integer from empty string";
    else {
        if (value[0] == '+') ++i;
        if (i == value.size()) reason = "invalid digit found in string";
        for (; i < value.size() && reason.empty(); ++i) {
            unsigned c = static_cast<unsigned char>(value[i]);
            if (c < '0' || c > '9') reason = "invalid digit found in string";
            else if (n > (UINT64_MAX - (c-'0')) / 10) reason = "number too large to fit in target type";
            else n = n*10 + c-'0';
        }
    }
    if (!reason.empty()) throw Failure(2, "error: invalid value '" + value + "' for '" + label(name) + "': " + reason + "\n" + footer);
