Options parse_options(int argc, char **argv) {
    std::string bin = argc > 0 ? argv[0] : "executable";
    auto slash = bin.find_last_of('/');
    if (slash != std::string::npos) bin.erase(0,slash+1);
    if (bin.empty()) bin = "executable";
    Options o;
    cpu_set_t cpus;
    if (sched_getaffinity(0,sizeof(cpus),&cpus) == 0) o.workers = std::max(1,CPU_COUNT(&cpus));
    else o.workers = std::max(1u,std::thread::hardware_concurrency());
    std::map<std::string,std::string> vals;
    std::vector<std::string> seen;
    bool end_flags = false;
    for (int i = 1; i < argc; ++i) {
        std::string token = argv[i];
        if (end_flags) unexpected(token,bin,seen,true);
        if (token == "--") { end_flags = true; continue; }
        std::string name, value;
        bool has_value = false;
        if (token.rfind("--",0) == 0) {
            size_t eq = token.find('=');
            name = token.substr(2,eq == std::string::npos ? eq : eq-2);
            if (!long_exists(name)) unexpected("--"+name,bin,seen);
            if (eq != std::string::npos) { has_value = true; value = token.substr(eq+1); }
        } else if (token.size() > 1 && token[0] == '-') {
            name = short_name(token[1]);
            if (name.empty()) unexpected(token.substr(0,2),bin,seen);
            if (token.size() > 2 && name != "help" && name != "version") {
                has_value = true; value = token.substr(token[2] == '=' ? 3 : 2);
            }
        } else unexpected(token,bin,seen,true);
        if (name == "help" || name == "version") {
            if (has_value) throw Failure(2,"error: unexpected value '"+value+"' for '--"+name+"' found; no more were expected\n\n"+usage(bin,{name})+footer);
            if (name == "help") throw Failure(0,help(bin),true);
            throw Failure(0,"zip-password-finder 0.10.3\n",true);
        }
        if (!has_value) {
            if (i+1 == argc) missing_value(name);
            std::string next = argv[i+1];
            if (next.size() > 1 && next[0] == '-') {
                if (next == "--") missing_value(name);
                if (next.rfind("--",0) == 0) {
                    auto raw = next.substr(2,next.find('=') == std::string::npos ? std::string::npos : next.find('=')-2);
                    if (long_exists(raw)) missing_value(name);
                    unexpected("--"+raw,bin,seen);
                } else {
                    if (!short_name(next[1]).empty()) missing_value(name);
                    unexpected(next.substr(0,2),bin,seen);
                }
            }
            value = next; ++i;
        }
        if (vals.count(name)) throw Failure(2,"error: the argument '"+label(name)+"' cannot be used multiple times\n\n"+full_usage(bin)+footer);
        if (name == "workers") o.workers = parse_number(value,name);
        else if (name == "minPasswordLen") o.min_length = parse_number(value,name);
        else if (name == "maxPasswordLen") o.max_length = parse_number(value,name);
        else if (name == "fileNumber") o.file_number = parse_number(value,name);
        else if (name == "inputFile") o.input = value;
        else if (name == "charset") o.charset_codes = value;
        else if (name == "passwordDictionary") o.dictionary = value;
        else if (name == "charsetFile") o.charset_file = value;
        else if (name == "startingPassword") o.starting = value;
        vals[name] = value;
        seen.push_back(name);
    }
    if (!vals.count("inputFile")) throw Failure(2,"error: the following required arguments were not provided:\n  --inputFile <inputFile>\n\n"+usage(bin,seen)+footer);
