void validate_options(Options &o) {
    if (!is_file(o.input)) cli_failure("'inputFile' does not exist");
    if (o.dictionary && !is_file(*o.dictionary)) cli_failure("'passwordDictionary' does not exist");
    if (o.charset_file && !is_file(*o.charset_file)) cli_failure("'charsetFile' does not exist");
    if (!o.workers) cli_failure("'workers' must be positive");
    if (!o.min_length) cli_failure("'minPasswordLen' must be positive");
    if (!o.max_length) cli_failure("'maxPasswordLen' must be positive");
    if (o.max_length < o.min_length) cli_failure("'maxPasswordLen' must be equal or greater than 'minPasswordLen'");
    if (o.dictionary) {
        if (o.starting) cli_failure("'startingPassword' cannot be used with a dictionary file");
        return;
    }
    if (o.charset_file) {
        auto bytes = read_file(*o.charset_file);
        bool valid;
        o.charset = decode_utf8(std::string(bytes.begin(),bytes.end()),&valid);
        if (!valid) io_failure("stream did not contain valid UTF-8");
    } else {
        for (auto c : decode_utf8(o.charset_codes)) {
            switch (c) {
            case U'l': o.charset += U"abcdefghijklmnopqrstuvwxyz"; break;
            case U'u': o.charset += U"ABCDEFGHIJKLMNOPQRSTUVWXYZ"; break;
            case U'd': o.charset += U"0123456789"; break;
            case U'h': o.charset += U"0123456789abcdef"; break;
            case U'H': o.charset += U"0123456789ABCDEF"; break;
            case U's': o.charset += U" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"; break;
            default: cli_failure("Unknown charset option '" + encode_utf8(std::u32string(1,c)) + "'");
            }
        }
    }
    std::sort(o.charset.begin(),o.charset.end());
    o.charset.erase(std::unique(o.charset.begin(),o.charset.end()),o.charset.end());
    if (o.starting) {
        auto s = decode_utf8(*o.starting);
        if (s.size() < o.min_length || s.size() > o.max_length) cli_failure("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration");
        for (auto c : s) if (!std::binary_search(o.charset.begin(),o.charset.end(),c)) cli_failure("'startingPassword' uses characters out of the generation charset");
    }
}
