std::string format_elapsed(uint64_t ns) {
    struct Unit { uint64_t count; const char *name; };
    static const Unit units[] = {
        {31557600000000000ull,"year"}, {2630016000000000ull,"month"},
        {86400000000000ull,"day"}, {3600000000000ull,"h"},
        {60000000000ull,"m"}, {1000000000ull,"s"}, {1000000ull,"ms"}, {1000ull,"us"}, {1ull,"ns"}
    };
    if (!ns) return "0s";
    std::string value;
    for (auto &unit : units) {
        uint64_t n = ns/unit.count;
