            if (offset > out.size() || length > limit-out.size()) throw BadStream{};
            for (unsigned i = 0; i < length; ++i) out.push_back(out[out.size()-offset]);
        }
    }
}
}
bool inflate64(const Bytes &input, uint64_t limit, Bytes &output) {
    if (limit > 512ull*1024*1024) return false;
    try {
        Bits bits(input);
        output.clear();
